def make_result(questions, answers, outcome="submitted", notice=None, shown=None):
    """questions：[{question, choices?, multi_select?}]（照 clarify 工具的参数）；answers：{"q0": 原始回答或 None, …}（照平台回调交回的）。
    走 Hermes 自己的 _normalize_questions 和 _result，返回结果行的正文（JSON 字符串）。"""
    normalized, error = _NS["_normalize_questions"](questions)
    assert error is None, error
    reply = {"answers": answers, "outcome": outcome}
    if notice:
        reply["notice"] = notice
    return _NS["_result"](normalized, reply, shown)
